# WebGL tone-mapping regression

`webgl-tone.ts` runs the actual game renderer in a browser, compares readback
against its direct-render reference, toggles quality/contact settings repeatedly,
and disposes every renderer and scene resource. A forced byte-target run checks
the no-float capability branch with an in-range color and neutral tape pass.
The normal run includes an HDR channel above 1 to catch premature clipping.
Both runs first render with tape and contact shadows requested, matching defaults.
The byte check keeps requesting contact shadows: the renderer must disable
unsupported GTAO automatically while preserving the tape pass. Byte targets
clip HDR values by design; the byte test does not claim HDR parity.

To run locally, temporarily create `src/app/tone-check/page.tsx`:

```tsx
"use client";
import { useEffect, useState } from "react";
import { checkWebGLTone } from "../../../tests/browser/webgl-tone";
let task: Promise<unknown>;
export default function Check() {
  const [result, setResult] = useState("running");
  useEffect(() => {
    task ??= (async () => ({
      hdr: await checkWebGLTone(),
      byte: await checkWebGLTone(true),
      fluorescent: await checkWebGLTone(false, "luminous"),
      lamp: await checkWebGLTone(false, "lampGlow"),
    }))();
    void task.then(value => setResult(JSON.stringify(value)))
      .catch(error => setResult(String(error)));
  }, []);
  return <pre>{result}</pre>;
}
```

Open `/tone-check?renderer=webgl` on the dev server. Each run must return
`maxDifference <= 1` and 16 samples; any GL error fails. Run it in an isolated
browser page because the byte check temporarily intercepts extension discovery.
Remove the temporary route afterward; it is not a game interface or production page.

Verified in Chromium: before the repair, the same flat surface changed from
RGB `[170,193,246]` to `[118,179,255]` when contact shadows were enabled.
After the repair all 16 HDR permutations match exactly, and the 16 byte-target
permutations also match their direct reference exactly. This numerical check
complements visual checks of the bright fluorescent opening room.


The two real fixture materials are also tested, using a fixed texel of the
production diffuser map for resolution-independent comparison. Their former
`toneMapped: false` policy bypassed ACES only during direct rendering; an output
pass cannot recover that per-material flag. They now use the common tone-mapped
policy, with warm HDR colors calibrated against the installed Three ACES curve
to preserve their former direct brightness. The direct path remains cheap.
Before normalization, the real fluorescent and lamp materials differed by 20
and 28 channel levels respectively across the contact toggle. After normalization,
each material's 16 permutations match exactly, and their output remains bright
and warm. This adds 32 fixture comparisons to the 32 surface/capability checks.

import * as THREE from "three";
import { createRenderer } from "../../src/lib/game/renderer";
import { createMaterials } from "../../src/lib/game/materials";

/** Browser integration check; run with ?renderer=webgl, outside the Node suite. */
export async function checkWebGLTone(forceByteTarget = false, fixture?: "luminous" | "lampGlow") {
  const original = WebGL2RenderingContext.prototype.getExtension;
  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(50, 1, 0.1, 100);
  camera.position.z = 3;
  const geometry = new THREE.PlaneGeometry(10, 10);
  const fixtureMaterials = fixture ? createMaterials() : undefined;
  const material = fixtureMaterials && fixture ? fixtureMaterials[fixture] : new THREE.MeshBasicMaterial({
    // The supported path must retain an HDR channel above 1. Byte targets are
    // intentionally checked only inside their representable color range.
    color: new THREE.Color(0.18, 0.45, forceByteTarget ? 0.75 : 2.5),
  });
  // Sample one actual diffuser texel independent of quality resolution.
  if (fixture) {
    const uv = geometry.getAttribute("uv");
    for (let i = 0; i < uv.count; i++) uv.setXY(i, 0.5, 0.5);
  }
  scene.add(new THREE.Mesh(geometry, material));
  const settings = { quality: "balanced" as const, tapeEffects: false, contactShadows: false };
  let renderer: Awaited<ReturnType<typeof createRenderer>> | undefined;
  try {
    if (forceByteTarget) {
      WebGL2RenderingContext.prototype.getExtension = function (this: WebGL2RenderingContext, name: string) {
        return (name === "EXT_color_buffer_float" || name === "EXT_color_buffer_half_float")
          ? null : Reflect.apply(original, this, [name]);
      } as typeof original;
    }
    renderer = await createRenderer(scene, camera, { ...settings, contactShadows: true, tapeEffects: true });
    if (renderer.backend !== "WebGL") throw new Error("Use ?renderer=webgl");
    renderer.resize(64, 64);
    const gl = renderer.canvas.getContext("webgl2")!;
    // Exercise real effect-enabled defaults before changing any preference.
    renderer.render(0, 0, 0);
    if (gl.getError() !== gl.NO_ERROR) throw new Error("WebGL error with default effects");
    if (forceByteTarget && renderer.canvas.dataset.contactShadows === "true")
      throw new Error("Unsupported AO still enabled");
    const samples: { quality: string; post: boolean; pixel: number[] }[] = [];
    for (const quality of ["balanced", "low", "high", "balanced"] as const)
      for (const post of [false, true, false, true]) {
        renderer.updateSettings({ ...settings, quality,
          // White AO on a single plane does not alter color. The byte fallback
          // must ignore the requested AO and still run its neutral tape pass.
          contactShadows: post,
          tapeEffects: forceByteTarget && post,
        });
        renderer.render(0, 0, 0);
        const pixel = new Uint8Array(4);
        gl.readPixels(32, 32, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, pixel);
        if (gl.getError() !== gl.NO_ERROR) throw new Error("WebGL error during setting toggle");
        samples.push({ quality, post, pixel: Array.from(pixel) });
      }
    const reference = samples[0].pixel;
    if (fixture && (!material.toneMapped || reference[0] < 225 || reference[1] < 215 || reference[2] >= reference[1]))
      throw new Error("Fixture must stay bright, warm, and use the common tone-mapping policy");
    const maxDifference = Math.max(...samples.flatMap(({ pixel }) =>
      pixel.slice(0, 3).map((channel, i) => Math.abs(channel - reference[i]))));
    if (maxDifference > 1) throw new Error(`Tone mapping changed by ${maxDifference} channel levels`);
    return { target: forceByteTarget ? "byte" : "half-float", fixture, reference, maxDifference, samples: samples.length };
  } finally {
    renderer?.dispose(); geometry.dispose();
    if (fixtureMaterials) fixtureMaterials.dispose();
    else material.dispose();
    WebGL2RenderingContext.prototype.getExtension = original;
  }
}

import assert from "node:assert/strict";
import test from "node:test";
import { Box3, Vector3 } from "three";
import { EntityNavigation } from "../src/lib/game/entity-navigation";
import { E, W, generateChunk } from "../src/lib/game/maze";

const from = { x: 2.4, z: 2.4 }, to = { x: 7.2, z: 2.4 };
function fixture() {
  const data = generateChunk(0, 0, 1);
  data.cells.fill(0);
  data.cells[0] = E; data.cells[1] = W;
  const barrier = new Box3(new Vector3(4.7, 0, 0), new Vector3(4.9, 3, 4.8));
  const nav = new EntityNavigation();
  nav.addSection("0,0", data, [barrier]);
  let checks = 0;
  const original = nav.clearSegment.bind(nav);
  nav.clearSegment = (a, b) => { checks++; return original(a, b); };
  return { data, barrier, nav, checks: () => checks };
}

test("identical failed routes skip searches while exact endpoint changes retry", () => {
  const { nav, checks } = fixture();
  assert.deepEqual(nav.route(from, to), []);
  const first = checks();
  assert.ok(first > 20, "fixture performs a real unsuccessful grid search");
  for (let i = 0; i < 100; i++) assert.deepEqual(nav.route({ ...from }, { ...to }), []);
  assert.equal(checks(), first);
  assert.deepEqual(nav.route({ ...from, x: from.x + 0.001 }, to), []);
  assert.ok(checks() > first, "different start retries even within the same navigation grid cell");
  const second = checks();
  assert.deepEqual(nav.route(from, { ...to, z: to.z + 0.001 }), []);
  assert.ok(checks() > second, "different destination retries");
});

test("section add, replacement, removal, and clear invalidate failed routes", () => {
  const { nav, data, barrier, checks } = fixture();
  nav.route(from, to);
  let previous = checks();
  nav.addSection("0,0", data, [barrier]);
  nav.route(from, to); assert.ok(checks() > previous); previous = checks();
  nav.addSection("1,0", generateChunk(1, 0, 1), []);
  nav.route(from, to); assert.ok(checks() > previous); previous = checks();
  nav.removeSection("1,0");
  nav.route(from, to); assert.ok(checks() > previous); previous = checks();
  nav.clear();
  nav.route(from, to); assert.ok(checks() > previous);
  nav.addSection("0,0", data, []);
  assert.deepEqual(nav.route(from, to), [to], "removing the blocking solid makes the destination reachable immediately");
});

test("failed-route storage evicts the oldest entry after 32 endpoint pairs", () => {
  const { nav, checks } = fixture();
  const start = (i: number) => ({ x: 2 + i * 0.005, z: 2.4 });
  for (let i = 0; i < 32; i++) assert.deepEqual(nav.route(start(i), to), []);
  const populated = checks();
  nav.route(start(0), to); assert.equal(checks(), populated);
  nav.route(start(32), to);
  const afterEviction = checks();
  nav.route(start(0), to); assert.ok(checks() > afterEviction);
});

test("successful detours retain clearance and return independent path arrays", () => {
  const { nav, data } = fixture();
  nav.addSection("0,0", data, [new Box3(new Vector3(4.7, 0, 0), new Vector3(4.9, 3, 3.2))]);
  const expected = nav.route(from, to);
  assert.ok(expected.length > 1);
  for (let i = 0; i < 10; i++) {
    const route = nav.route(from, to);
    assert.deepEqual(route, expected);
    let previous = from;
    for (const point of route) { assert.ok(nav.clearSegment(previous, point)); previous = point; }
    route[0].x += 100;
  }
  assert.deepEqual(nav.route(from, to), expected);
});

import assert from "node:assert/strict";
import test from "node:test";
import { createHash } from "node:crypto";
import { EntityNavigation } from "../src/lib/game/entity-navigation";
import { generateChunk } from "../src/lib/game/maze";
import { buildSection, type Section } from "../src/lib/game/world";
import { headlessMaterials } from "./helpers/materials";
import { Stalker } from "../src/lib/game/stalker";

test("real tape preserves pursuing behavior while only the first identical failure searches", () => {
  const materials = headlessMaterials();
  const navigation = new EntityNavigation();
  const sections: Section[] = [];
  try {
    for (let z = -1; z <= 1; z++) {
      for (let x = -1; x <= 1; x++) {
        const data = generateChunk(x, z, 48);
        const section = buildSection(data, materials, 0);
        sections.push(section);
        navigation.addSection(`${x},${z}`, data, section.colliders);
      }
    }
    const player = { x: -2.4, y: 1.66, z: 60 };
    const input = {
      view: {
        position: player,
        forward: { x: 0, y: 0, z: -1 },
        up: { x: 0, y: 1, z: 0 },
        fov: 68,
        aspect: 16 / 9,
      },
      playerSpeed: 4,
      canGrab: false,
    };
    const stalker = new Stalker(48, navigation);
    stalker.stage({ x: 2.4, z: 55.2 }, player, true);
    const originalRoute = navigation.route.bind(navigation);
    const originalClearSegment = navigation.clearSegment.bind(navigation);
    let requests = 0, segmentChecks = 0, searches = 0, footsteps = 0;
    navigation.clearSegment = (from, to) => {
      segmentChecks++;
      return originalClearSegment(from, to);
    };
    navigation.route = (from, to) => {
      const previousChecks = segmentChecks;
      const path = originalRoute(from, to);
      if (segmentChecks > previousChecks) searches++;
      requests++;
      return path;
    };
    const trace = createHash("sha256");
    for (let frame = 0; frame < 900; frame++) {
      stalker.update(1 / 30, input, () => footsteps++);
      trace.update(JSON.stringify([
        stalker.phase,
        stalker.position.toArray(),
        stalker.gait,
        stalker.heading,
        stalker.speed,
      ]));
    }
    assert.equal(requests, 33);
    assert.equal(searches, 1);
    assert.equal(footsteps, 0);
    // Captured from the same real tape simulation before failure caching.
    assert.equal(
      trace.digest("hex"),
      "066a8605f2e5e816597f77edd7b4858a4c4b0ec413979d0f5675768786c08a66",
    );
  } finally {
    for (const section of sections) section.dispose();
    navigation.clear();
    materials.dispose();
  }
});

