        box([0.06, 0.008, depth + 0.024], rotate([0, height + 0.044, 0]), mats.enamel, face);
        box([0.19, 0.09, 0.01], rotate([-0.12, height * 0.5, -depth / 2 - 0.002]), mats.paper, face);
