      if (design === 2) {
        for (let i = 0; i < 3; i++) {
          const angle = (i * Math.PI * 2) / 3;
          strut([Math.cos(angle) * 0.3, 0.01, Math.sin(angle) * 0.3], [0, 1.1, 0], 0.016, mats.wood);
