        strut([x, 1.89, -1.12], [x, 1.89, -0.48], 0.055, rails);
        strut([x, 1.89, -0.48], [x, 1.52, -0.48], 0.055, rails);
      }
      for (let i = 1; i <= 6; i++) {
        const y = i * 0.232;
        const z = -1.48 + (y / 1.866) * 0.36;
        strut([-0.43, y, z], [0.43, y, z], 0.045, mats.wood);
      }
      const top = new THREE.Vector3(0, 1.49, -0.51);
      const bottom = new THREE.Vector3(0, 0.16, 1.34);
      const chute = new THREE.BoxGeometry(0.87, 0.085, top.distanceTo(bottom));
      chute.rotateX(Math.atan2(top.y - bottom.y, bottom.z - top.z));
      add(
        chute,
        chuteMat,
        top.add(bottom).multiplyScalar(0.5).toArray() as Point,
      );
      for (const x of [-0.45, 0.45]) {
        strut([x, 1.6, -0.54], [x, 0.27, 1.38], 0.065, deck);
      }
      cushion([0.88, 0.13, 0.36], [0, 0.105, 1.41], chuteMat, 0.035);
      // A broad foot joins the two rails and makes the slide touch the carpet.
      box([1.02, 0.11, 0.28], [0, 0.055, 1.31], rails);
      anchor.set(0, 1.48, -0.85);
      break;
    }
    case "springHorse": {
      const body = [mats.enamel, mats.cream, mats.fadedRed][design];
      const trim = design === 2 ? mats.enamel : mats.fadedRed;
      cylinder(0.33, 0.36, 0.07, [0, 0.035, 0], mats.metal);
      const coil: THREE.Vector3[] = [];
      for (let i = 0; i <= 80; i++) {
        const t = i / 80;
        const angle = t * Math.PI * 10;
        coil.push(
          new THREE.Vector3(
            Math.cos(angle) * 0.16,
            0.08 + t * 0.77,
            Math.sin(angle) * 0.16,
          ),
        );
      }
      add(
        new THREE.TubeGeometry(
          new THREE.CatmullRomCurve3(coil),
          80,
          0.035,
          6,
          false,
        ),
        mats.metal,
        [0, 0, 0],
      );
      box([0.5, 0.13, 0.36], [0, 0.9, 0], trim);
      ellipsoid([1.18, 0.63, 0.4], [0, 1.2, 0], body);
      ellipsoid([0.39, 0.72, 0.32], [0.39, 1.49, 0], body);
      ellipsoid([0.57, 0.39, 0.35], [0.55, 1.78, 0], body);
      cushion([0.39, 0.21, 0.32], [0.73, 1.71, 0], body, 0.07);
      for (const z of [-0.105, 0.105]) {
        ellipsoid([0.12, 0.29, 0.095], [0.42, 1.99, z], trim);
        ellipsoid(
          [0.07, 0.07, 0.018],
          [0.65, 1.835, z < 0 ? -0.158 : 0.158],
          mats.wood,
        );
      }
      cushion([0.51, 0.11, 0.45], [-0.13, 1.493, 0], trim, 0.035);
      strut([0.37, 1.6, -0.34], [0.37, 1.6, 0.34], 0.035, mats.wood);
      strut([-0.05, 0.97, -0.42], [-0.05, 0.97, 0.42], 0.055, mats.wood);
      for (const x of [-0.34, 0.31]) {
        strut([x, 1.06, -0.09], [x - 0.11, 0.79, -0.09], 0.085, body);
      }
      strut([-0.51, 1.29, 0], [-0.73, 1.01, 0], 0.075, trim);
      anchor.set(0, 1.2, 0);
      break;
    }
    case "blocks": {
      // Giant letter blocks rest face-to-face: two on the carpet and one
      // balanced across both, or a crooked single tower.
      const size = 0.72;
      const half = size / 2;
      const inks = [mats.enamel, mats.fadedRed, mats.fabric];
      const order = [[0, 1, 2], [1, 2, 0], [2, 0, 1]][design];
      const spots: [number, number, number, number][] = design === 2
        ? [[0, half, 0, 0], [0.05, half + size, 0.03, 0.22], [-0.03, half + size * 2, 0.01, -0.18]]
        : [[-0.4, half, 0.08, 0.05], [0.4, half, 0.02, -0.07], [vary(-0.06, 0.08), half + size, 0.05, design === 1 ? 0.45 : 0.12]];
      spots.forEach(([x, y, z, yaw], i) => {
        const color = inks[order[i]];
        const face: Point = [0, yaw, 0];
        const at = (dx: number, dy: number, dz: number): Point => [
          x + dx * Math.cos(yaw) + dz * Math.sin(yaw),
          y + dy,
          z - dx * Math.sin(yaw) + dz * Math.cos(yaw),
        ];
        cushion([size, size, size], [x, y, z], color, 0.045, face);
        box([0.57, 0.57, 0.012], at(0, 0, -half - 0.004), mats.cream, face);
        const front = -half - 0.016;
        const glyph = ["A", "B", "C"][(i + design) % 3];
        // Seen from the front (-Z), the viewer's right is -X: mirror strokes.
        const stroke = (w: number, h: number, dx: number, dy: number, roll = 0) =>
          box([w, h, 0.012], at(-dx, dy, front), color, [0, yaw, -roll]);
        if (glyph === "A") {
          stroke(0.055, 0.38, -0.1, 0, -0.28);
          stroke(0.055, 0.38, 0.1, 0, 0.28);
          stroke(0.19, 0.05, 0, -0.015);
        } else if (glyph === "B") {
          stroke(0.055, 0.38, -0.115, 0);
          for (const dy of [-0.16, 0, 0.16]) stroke(0.22, 0.05, -0.01, dy);
          for (const dy of [-0.08, 0.08]) stroke(0.055, 0.14, 0.1, dy);
        } else {
          stroke(0.055, 0.37, -0.115, 0);
          for (const dy of [-0.16, 0.16]) stroke(0.27, 0.05, 0.005, dy);
        }
      });
      anchor.set(spots[0][0], spots[0][1], spots[0][2]);
      break;
    }
  }

  return { parts, bounds, anchor, ...(chairFrame ? { chair: chairFrame } : {}) };
}

import * as THREE from "three";
import { ConvexGeometry } from "three/addons/geometries/ConvexGeometry.js";
import {
  FINGERS,
  restHip,
  rollEntityBody,
  type EntityBody,
  type EntityHead,
  type EntityVariant,
} from "./entity-anatomy";
import {
  sculptEntitySurface,
  skinEntitySurface,
  type EntitySurface,
  type Tissue,
} from "./entity-skin";
import {
  gaitUrgency,
  solveEntityLeg,
  stepLength,
} from "./entity-gait";

type Leg = { hip: THREE.Bone; knee: THREE.Bone; ankle: THREE.Bone; length: number };
type Arm = { shoulder: THREE.Bone; elbow: THREE.Bone; hand: THREE.Bone };
type Head = { bone: THREE.Bone; jaw?: THREE.Bone; head: EntityHead; phase: number };
type Rig = {
  hips: THREE.Bone;
  chest: THREE.Bone;
  heads: Head[];
  legs: Leg[];
  arms: Arm[];
  fingers: { bone: THREE.Bone; side: number; index: number }[];
  anatomy: Tissue[];
};

/** Bones and smooth tissue for one body. Needs no material, so workers can sculpt it. */
function rigEntity(parent: THREE.Object3D, body: EntityBody, material?: THREE.Material): Rig {
  const anatomy: Tissue[] = [];
  const tissue = (bone: THREE.Bone, x: number, y: number, z: number, sx: number, sy: number, sz: number, blend?: number) => {
    anatomy.push({ bone, center: new THREE.Vector3(x, y, z), radii: new THREE.Vector3(sx, sy, sz), blend });
  };
  const skin = (bone: THREE.Bone, length: number, radius: number, curve = 0.01, blend = 0.026) => {
    anatomy.push({ bone,
      center: new THREE.Vector3(0, -length / 2, 0),
      radii: new THREE.Vector3(radius + Math.abs(curve), length / 2 + radius, radius),
      length, radius, curve, blend,
    });
  };
  const { build: b, limbs: g, torso } = body;
  const t = torso / 0.86;
  const w = body.shoulders / 0.24;
  const hips = new THREE.Bone(), chest = new THREE.Bone();
  hips.position.y = restHip(body);
  parent.add(hips);
  // Trunk masses melt together with a wide blend: no segmented, insect waist.
  const trunk = 0.07;
  // Pelvis with iliac crests and a slack seat, so the legs root into a mass.
  tissue(hips, 0, 0.01, 0, 0.13 * b, 0.12, 0.08 * b, trunk);
  for (const side of [-1, 1]) {
    tissue(hips, side * 0.095 * b, 0.05, 0.01, 0.05, 0.05, 0.05, trunk);
    tissue(hips, side * 0.066 * b, -0.055, -0.04, 0.068 * b, 0.08, 0.06 * b, 0.04);
  }
  chest.position.set(0.025, torso, 0);
  hips.add(chest);
  skin(chest, torso, 0.084 * b, -0.022, trunk);
  // Ribcage over a narrow waist, and a belly that only sags on some bodies.
  tissue(chest, -0.005, -0.22 * t, 0.012, 0.13 * b, 0.23 * t, 0.092 * b, trunk);
  tissue(chest, 0, -0.66 * t, 0.012 + body.belly * 0.035,
    (0.088 + body.belly * 0.04) * b, (0.15 + body.belly * 0.04) * t, (0.062 + body.belly * 0.05) * b, trunk);
  tissue(chest, 0, -0.028, -0.009, 0.235 * w, 0.094, 0.079 * b);
  for (const side of [-1, 1]) {
    // Sloping trapezius and swept shoulder blades erase the horizontal bar.
    tissue(chest, side * 0.085 * w, 0.025, -0.012, 0.098, 0.086, 0.058);
    tissue(chest, side * 0.078 * w, -0.16, -0.036, 0.066, 0.155, 0.058);
    // Flat, wasted pectorals over the ribs.
    tissue(chest, side * 0.075 * w, -0.1, 0.045 * b, 0.078, 0.06, 0.036);
    // Clavicles run from the throat to each shoulder.
    tissue(chest, side * 0.12 * w, 0.012, 0.035, 0.1 * w, 0.018, 0.02, 0.012);
  }
  if (body.spine > 0.35) {
    // A vertebral ridge shows through the back of the thinnest bodies.
    const knuckle = 0.013 + body.spine * 0.01;
    for (let bone = 0; bone < 6; bone++)
      tissue(chest, 0, -0.06 - bone * 0.11 * t, -0.078 * b - 0.004, knuckle, knuckle * 1.1, knuckle, 0.01);
  }
  const heads: Head[] = [];
  body.heads.forEach((head, index) => {
    const s = head.size, st = head.stretch;
    const neck = new THREE.Bone(), bone = new THREE.Bone();
    const offset = body.heads.length > 1 ? (index ? -1 : 1) * 0.075 * w : 0;
    // The neck bone sits at the head end; its skin runs back down to the chest.
    neck.position.set(0.025 + offset + Math.sin(head.splay) * head.neck, Math.cos(head.splay) * head.neck, 0.01);
    neck.rotation.z = -head.splay;
    chest.add(neck);
    skin(neck, head.neck, (head.kind === "bulb" || head.kind === "pin" ? 0.036 : 0.044) * Math.sqrt(g), -0.008);
    bone.position.set(0.015, 0.13, 0.015);
    bone.name = index ? `head-${index}` : "head";
    neck.add(bone);
    let jaw: THREE.Bone | undefined;
    // A throat bridges the neck to even the smallest head.
    if (head.kind !== "pyramid") tissue(bone, 0, -0.075, 0.008, 0.034, 0.075, 0.033);
    switch (head.kind) {
      case "pyramid": {
        // A broad, faceted head with a forward-leaning apex; still fits the doors.
        // Truncated ridges catch only a hairline of light. The primary planes stay
        // severe, with an off-axis apex and an asymmetric, undercut lower rim.
        if (!material) break;
        const corners = [
          new THREE.Vector3(-0.318, -0.34, -0.356),
          new THREE.Vector3(0.318, -0.34, -0.356),
          new THREE.Vector3(0.318, -0.36, 0.356),
          new THREE.Vector3(-0.318, -0.36, 0.356),
          new THREE.Vector3(0.024, 0.36, 0.16),
        ].map(corner => corner.multiplyScalar(s));
        const edges = [[0, 1], [1, 2], [2, 3], [3, 0], [0, 4], [1, 4], [2, 4], [3, 4]];
        const bevel = edges.flatMap(([a, c]) => [
          corners[a].clone().lerp(corners[c], 0.024),
          corners[c].clone().lerp(corners[a], 0.024),
        ]);
        const skull = new THREE.Mesh(new ConvexGeometry(bevel), material);
        skull.castShadow = skull.receiveShadow = true;
        skull.name = "pyramid-head";
        skull.position.y = 0.02;
        bone.add(skull);
        break;
      }
      case "skull":
        // A continuous cranial envelope: narrow jaw, swept occiput, no face.
        tissue(bone, 0, 0.025, -0.018, 0.125 * s, 0.207 * s * st, 0.116 * s);
        tissue(bone, -0.015, -0.11 * s, 0.017, 0.086 * s, 0.105 * s, 0.082 * s);
        break;
      case "bulb":
        // Swollen cranium over a small receding chin.
        tissue(bone, 0, 0.08 * s, -0.03, 0.17 * s, 0.19 * s, 0.18 * s);
        tissue(bone, 0, -0.08 * s, 0.035, 0.058 * s, 0.075 * s, 0.058 * s);
        break;
      case "long": {
        // A tall, backswept egg of a skull.
        const crown = new THREE.Bone();
        crown.rotation.x = -0.38;
        bone.add(crown);
        tissue(crown, 0, 0.13 * s * st, -0.02, 0.092 * s, 0.28 * s * st, 0.1 * s);
        tissue(bone, 0, -0.07 * s, 0.025, 0.074 * s, 0.1 * s, 0.07 * s);
        break;
      }
      case "jaw":
        // Cranium with an unhinged lower jaw hanging open beneath it.
        tissue(bone, 0, 0.05 * s, -0.02, 0.12 * s, 0.165 * s * st, 0.118 * s);
        jaw = new THREE.Bone();
        jaw.position.set(0, -0.05 * s, -0.05 * s);
        jaw.rotation.x = 0.55;
        bone.add(jaw);
        // Hinged at the back of the skull, the long jaw gapes forward.
        tissue(jaw, 0, -0.03 * s, 0.1 * s, 0.068 * s, 0.03 * s, 0.11 * s, 0.006);
        break;
      case "pin":
        // A head far too small for the body.
        tissue(bone, 0, 0, 0, 0.062 * s, 0.085 * s, 0.066 * s);
        break;
      case "slab":
        // A flat, faceless board of a head.
        tissue(bone, 0, 0.03, 0, 0.16 * s, 0.19 * s * st, 0.048 * s);
        tissue(bone, 0, -0.13 * s, 0.01, 0.085 * s, 0.06 * s, 0.045 * s);
        break;
    }
    heads.push({ bone, jaw, head, phase: index * 2.1 + body.seed % 7 });
  });
  const legs: Leg[] = [], arms: Arm[] = [], fingers: Rig["fingers"] = [];
  for (const side of [-1, 1]) {
    const L = body.legs[side < 0 ? 0 : 1];
    const hip = new THREE.Bone(), knee = new THREE.Bone(), ankle = new THREE.Bone();
    hip.name = side < 0 ? "left-hip" : "right-hip";
    knee.name = side < 0 ? "left-knee" : "right-knee";
    ankle.name = side < 0 ? "left-ankle" : "right-ankle";
    hip.position.x = side * 0.13 * (0.9 + b * 0.1);
    skin(hip, L, 0.05 * g, side * 0.008);
    // Quadriceps and hamstrings taper the thigh toward the knee.
    tissue(hip, side * 0.004, -0.3 * L, 0.014, 0.056 * g, 0.26 * L, 0.054 * g);
    tissue(hip, 0, -0.45 * L, -0.016, 0.044 * g, 0.21 * L, 0.042 * g);
    knee.position.y = -L;
    skin(knee, L, 0.034 * g, -side * 0.008);
    tissue(knee, 0, 0, 0.012, 0.036 * g, 0.042, 0.032);
    tissue(knee, 0, -0.28 * L, -0.022, 0.043 * g, 0.17 * L, 0.044 * g);
    ankle.position.y = -L;
    // Heel, long sole and a narrow instep.
    tissue(ankle, 0, -0.012, -0.012, 0.038, 0.04, 0.048);
    tissue(ankle, 0, -0.018, 0.085, 0.05, 0.032, 0.13);
    knee.add(ankle);
    hip.add(knee);
    hips.add(hip);
    legs.push({ hip, knee, ankle, length: L });
    const plan = body.arms[side < 0 ? 0 : 1];
    const U = plan.upper, F = plan.fore, p = plan.palm;
    const shoulder = new THREE.Bone(), elbow = new THREE.Bone(), hand = new THREE.Bone();
    shoulder.position.set(side * body.shoulders, -plan.droop, 0);
    shoulder.rotation.z = side * 0.14;
    shoulder.name = side < 0 ? "left-shoulder" : "right-shoulder";
    hand.name = side < 0 ? "left-hand" : "right-hand";
    // Shoulder roots grow inward into the clavicle instead of ball sockets.
    tissue(shoulder, -side * 0.038, -0.012, -0.003, 0.089, 0.075, 0.062);
    tissue(shoulder, side * 0.01, -0.07, 0, 0.056 * g, 0.105, 0.054 * g);
    skin(shoulder, U, 0.038 * g, side * 0.016);
    tissue(shoulder, 0, -0.5 * U, 0.012, 0.039 * g, 0.2 * U, 0.037 * g);
    elbow.position.y = -U;
    skin(elbow, F, 0.026 * g, -side * 0.013);
    tissue(elbow, 0, 0.014, -0.008, 0.032, 0.054, 0.032);
    tissue(elbow, 0, -0.2 * F, 0.004, 0.036 * g, 0.19 * F, 0.031 * g);
    hand.position.y = -F;
    const count = FINGERS[plan.hand];
    if (plan.hand === "mitten") {
      // A swollen, fused paddle.
      tissue(hand, 0, -0.1 * p, 0.01, 0.05 * p, 0.12 * p, 0.034 * p);
    } else {
      const wide = plan.hand === "splay" ? 0.038 : plan.hand === "claw" ? 0.026 : 0.03;
      tissue(hand, 0, -0.055 * p, 0.005, wide * p, 0.083 * p, 0.022 * p);
    }
    for (let finger = 0; finger < count; finger++) {
      const index = finger - (count - 1) / 2;
      const joint = new THREE.Bone();
      const spacing = plan.hand === "splay" ? 0.016 : plan.hand === "claw" ? 0.017 : 0.02;
      joint.position.set(index * spacing * p, -0.1 * p, 0.006);
      joint.rotation.z = index * (plan.hand === "splay" ? 0.2 : 0.17);
      fingers.push({ bone: joint, side, index });
      hand.add(joint);
      const [length, radius, curve] =
        plan.hand === "claw" ? [0.21, 0.012, 0.03]
        : plan.hand === "twig" ? [0.23 - Math.abs(index) * 0.02, 0.0105, 0.018]
        : plan.hand === "splay" ? [0.15 - Math.abs(index) * 0.018, 0.0095, 0.012]
        : [0.135 - Math.abs(index) * 0.024, 0.011, 0.014];
      skin(joint, length * p, radius, index * curve + (plan.hand === "claw" ? side * 0.012 : 0), 0.006);
    }
    elbow.add(hand);
    shoulder.add(elbow);
    chest.add(shoulder);
    arms.push({ shoulder, elbow, hand });
  }
  return { hips, chest, heads, legs, arms, fingers, anatomy };
}

function bonesOf(root: THREE.Object3D) {
  const bones: THREE.Bone[] = [];
  root.traverse(object => { if (object instanceof THREE.Bone) bones.push(object); });
  return bones;
}

/** Worker entry: the whole skinned surface for one appearance, as plain arrays. */
export function sculptEntity(variant: EntityVariant, seed: number) {
  const root = new THREE.Group();
  const rig = rigEntity(root, rollEntityBody(variant, seed));
  root.updateMatrixWorld(true);
  return sculptEntitySurface(rig.anatomy, bonesOf(root));
}

/** Soft, continuous anatomy; each seed grows a different long, narrow relative. */
export class EntityModel extends THREE.Group {
  readonly body: EntityBody;
  readonly variant: EntityVariant;
  /** False until a surface exists; the skeleton alone is invisible. */
  readonly sculpted: boolean;
  private hips: THREE.Bone;
  private chest: THREE.Bone;
  private heads: Head[];
  private legs: Leg[];
  private arms: Arm[];
  private fingers: Rig["fingers"];
  private motion = 0;
  private reach = 0;
  private down = new THREE.Vector3(0, -1, 0);
  private upper = new THREE.Vector3();
  private lower = new THREE.Vector3();
  private inverse = new THREE.Quaternion();
  private armPose = new THREE.Quaternion();
  /**
   * @param seed 0 grows the canonical body.
   * @param surface Pre-sculpted bind-pose surface; `null` leaves the model unskinned.
   */
  constructor(material: THREE.Material, variant: EntityVariant = "stalker", seed = 0, surface?: EntitySurface | null) {
    super();
    this.variant = variant;
    this.name = variant;
    this.body = rollEntityBody(variant, seed);
    const rig = rigEntity(this, this.body, material);
    ({ hips: this.hips, chest: this.chest, heads: this.heads, legs: this.legs, arms: this.arms, fingers: this.fingers } = rig);
    this.updateMatrixWorld(true);
    const bones = bonesOf(this);
    if (surface === undefined) surface = sculptEntitySurface(rig.anatomy, bones);
    this.sculpted = surface !== null;
    if (surface) this.add(skinEntitySurface(surface, bones, material));
    this.visible = false;
    this.animate(0, false, 0, 1);
  }
  get seed() {
    return this.body.seed;
  }
  animate(gait: number, moving: boolean, speed: number, dt: number, reach = 0, squeeze = 0, struggle = 0) {
    this.motion += ((moving ? 1 : 0) - this.motion) * Math.min(1, dt * 8);
    this.reach += (reach - this.reach) * Math.min(1, dt * 4);
    const rush = gaitUrgency(speed);
    const heavy = this.variant === "pyramid";
    const { hunch, lean } = this.body;
    // Rise over the supporting foot instead of walking in a permanent crouch.
    // The shorter leg sets the height; a longer one stays bent, and limps.
    const leg = Math.min(...this.body.legs);
    const rest = restHip(this.body);
    const stance = ((((gait + Math.PI / 2) / Math.PI) % 1) + 1) % 1;
    const plantedZ = (0.5 - stance) * stepLength(speed) * this.motion;
    const supportHeight =
      Math.sqrt((leg * 2 - 0.008) ** 2 - plantedZ ** 2) + 0.05;
    const hipHeight = rest + (supportHeight - rest) * this.motion;
    this.hips.position.y = hipHeight;
    this.hips.rotation.z = (this.body.legs[1] - this.body.legs[0]) * 0.5 * this.motion
      * Math.sin(gait);
    this.legs.forEach(({ hip, knee, ankle, length }, i) => {
      const phase = gait + i * Math.PI;
      const pose = solveEntityLeg(phase, speed, this.motion, hipHeight, length);
      hip.rotation.x = pose.hip;
      knee.rotation.x = pose.knee;
      ankle.rotation.x = pose.ankle;
      const arm = this.arms[i],
        lag = Math.sin(phase - (heavy ? 0.58 : 0.28));
      // A dropped shoulder drags its arm with less swing.
      const drag = 1 - this.body.arms[i].droop * 5;
      arm.shoulder.rotation.x = -lag * (0.25 + rush * 0.32) * this.motion * drag - hunch * 1.05;
      arm.shoulder.rotation.y = Math.sin(phase - 0.6) * 0.065 * this.motion;
      arm.shoulder.rotation.z = (i ? 1 : -1) * (0.065 + (1 + Math.sin(phase - 0.4)) * 0.022 * this.motion);
      arm.elbow.rotation.set(0, 0, 0);
      arm.elbow.rotation.x =
        -0.13 - rush * (heavy ? 0.42 : 0.6) - Math.max(0, -lag) * 0.19 * this.motion;
      arm.hand.rotation.x = 0.06 + Math.sin(phase - 0.5) * 0.09 * this.motion;
      arm.elbow.rotation.y = Math.sin(phase - 0.5) * (heavy ? 0.055 : 0.095) * this.motion;
      arm.hand.rotation.z = Math.sin(phase - 0.85) * 0.075 * this.motion;
      if (this.reach > 0.001) {
        const side = i ? 1 : -1;
        // Open elbows and forward palms become an enclosing, inward forearm arc.
        this.upper.set(side * (0.62 - squeeze * 0.05), -0.3 - squeeze * 0.15, 0.66 - squeeze * 0.2).normalize();
        this.armPose.setFromUnitVectors(this.down, this.upper);
        arm.shoulder.quaternion.slerp(this.armPose, this.reach);
        this.lower.set(side * (0.08 - squeeze * 0.98), -0.27, 0.9 - squeeze * 0.45).normalize();
        this.inverse.copy(arm.shoulder.quaternion).invert();
        this.lower.applyQuaternion(this.inverse);
        this.armPose.setFromUnitVectors(this.down, this.lower);
        arm.elbow.quaternion.slerp(this.armPose, this.reach);
        arm.hand.rotation.x = -0.22 - squeeze * 0.65;
      }
    });
    this.chest.rotation.x = hunch * (1 - this.reach * 0.5) + (heavy ? 0.095 : 0.035) + rush * 0.16
      + squeeze * 0.22 + Math.abs(struggle) * 0.09;
    this.chest.rotation.y = Math.sin(gait - (heavy ? 0.5 : 0.25)) * (heavy ? 0.065 : 0.045) * this.motion;
    this.chest.rotation.z = lean - Math.sin(gait) * 0.028 * this.motion + struggle * 0.075;
    for (const { bone, jaw, head, phase } of this.heads) {
      // Each head lolls on its own; the chest's hunch is mostly looked past.
      bone.rotation.z = head.tilt - (head.splay ? 0 : 0.09)
        - Math.sin(gait * 0.5 - 0.5 + phase) * 0.025 * this.motion - struggle * 0.09;
      bone.rotation.x = -hunch * 0.8 - rush * 0.1 + this.reach * 0.18 + squeeze * 0.12
        + Math.sin(gait * 2 - (heavy ? 0.8 : 0.3) + phase) * (heavy ? 0.028 : 0.012) * this.motion;
      bone.rotation.y = -this.chest.rotation.y * 0.7 + (this.heads.length > 1 ? Math.sin(phase) * 0.2 : 0);
      if (jaw) jaw.rotation.x = 0.55 + this.reach * 0.3 + squeeze * 0.2
        + Math.sin(gait * 3 + phase) * 0.03 * this.motion;
    }
    for (const { bone, side, index } of this.fingers) {
      bone.rotation.x = -0.16 - Math.abs(index) * 0.16 - this.reach * (0.24 + squeeze * 0.55)
        + Math.sin(gait - 0.9 + index * 0.55 + side) * 0.08 * this.motion;
      bone.rotation.z = index * (0.13 + this.reach * 0.12);
    }
  }
}

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import test from "node:test";
import { CHUNK, E, W, generateChunk, landmarkKind } from "../src/lib/game/maze";

test("optimized classification preserves established tapes across negative district and band seams", () => {
  // Captured from ce5e024 before replacing the 24-slot candidate arrays.
  // This freezes room identity only, allowing intentional room-interior refinements.
  const digest = createHash("sha256");
  for (const seed of [0, 1, 48, 60, 199307, 882731, 2147483647, -17])
    for (let z = -30; z <= 30; z++)
      for (let x = -30; x <= 30; x++)
        digest.update(landmarkKind(x, z, seed) + ",");
  assert.equal(digest.digest("hex"), "bd293b3cf3ed13f99107ec5a995f8a167cedae0f35349bab2611afc77851c29f");
});

test("direct corridor gate classification matches both neighbors at district boundaries", () => {
  for (const seed of [0, 1, 48, 199307, -17])
    for (const x of [-25, -24, -7, -6, -1, 0, 5, 6, 23, 24])
      for (const z of [-6, 0, 5]) {
        const left = generateChunk(x, z, seed, 0), right = generateChunk(x + 1, z, seed, 13);
        const continuous = left.landmark.kind === "corridor" && right.landmark.kind === "corridor";
        let gates = 0;
        for (let row = 0; row < CHUNK; row++) {
          const a = Boolean(left.cells[row * CHUNK + CHUNK - 1] & E);
          const b = Boolean(right.cells[row * CHUNK] & W);
          assert.equal(a, b);
          if (a) { gates++; if (continuous) assert.equal(row, 6); }
        }
        assert.equal(gates, 1);
      }
});

import assert from "node:assert/strict";
import test from "node:test";
import * as THREE from "three";
import { EntityModel } from "../src/lib/game/entity-model";

for (const variant of ["stalker", "pyramid"] as const) {
  test(`${variant} has finite normalized skinning across anatomical joints`, () => {
    const material = new THREE.MeshBasicMaterial();
    const entity = new EntityModel(material, variant);
    const skin = entity.getObjectByName("continuous-void-skin") as THREE.SkinnedMesh;
    assert.ok(skin.isSkinnedMesh);
    const weights = skin.geometry.getAttribute("skinWeight");
    const indices = skin.geometry.getAttribute("skinIndex");
    const positions = skin.geometry.getAttribute("position");
    assert.ok(positions.count < 180000, "bounded surface geometry");
    const blended = new Set<string>();
    for (let vertex = 0; vertex < positions.count; vertex++) {
      let sum = 0;
      const attached: THREE.Bone[] = [];
      for (let slot = 0; slot < 4; slot++) {
        const weight = weights.getComponent(vertex, slot);
        assert.ok(Number.isFinite(weight) && weight >= 0 && weight <= 1);
        sum += weight;
        const bone = skin.skeleton.bones[indices.getComponent(vertex, slot)];
        assert.ok(bone);
        if (weight > 0.1) attached.push(bone);
      }
      assert.ok(Math.abs(sum - 1) < 1e-6);
      if (attached.length > 1) attached.forEach(bone => blended.add(bone.name));
      assert.ok(Number.isFinite(positions.getX(vertex)) && Number.isFinite(positions.getY(vertex)) && Number.isFinite(positions.getZ(vertex)));
    }
    for (const side of ["left", "right"]) {
      for (const joint of ["knee", "hand", "shoulder"]) {
        assert.ok(blended.has(`${side}-${joint}`), `skin distributes bending at ${side} ${joint}`);
      }
    }
    entity.traverse(object => {
      if (object instanceof THREE.Mesh) object.geometry.dispose();
      if (object instanceof THREE.SkinnedMesh) object.skeleton.dispose();
    });
    material.dispose();
  });
}

import assert from "node:assert/strict";
import test from "node:test";
import { Box3, Vector3 } from "three";
import { CharacterMotor } from "../src/lib/game/physics";
import { generateChunk, CELL } from "../src/lib/game/maze";

test("Rapier capsule stops at a wall and slides along it", async () => {
  const position = new Vector3(CELL * 2.5, 1.66, CELL * 4.5),
    motor = await CharacterMotor.create(position);
  const wall = new Box3(new Vector3(13, 0, 17), new Vector3(13.2, 3, 25));
  motor.addSection("0,0", generateChunk(0, 0, 199307), [wall]);
  for (let i = 0; i < 120; i++) motor.move(0.04, -0.015, 1 / 60, position);
  assert.ok(position.x < 12.81, `stopped before wall: ${position.x}`);
  assert.ok(position.z < 20.4, `slid along wall: ${position.z}`);
  assert.ok(
    position.y > 1.6 && position.y < 1.8,
    `remained on floor: ${position.y}`,
  );
  motor.dispose();
});
test("streamed floors and noclip teleports keep the capsule grounded", async () => {
  const position = new Vector3(12, 1.66, 21.6),
    motor = await CharacterMotor.create(position);
  motor.addSection("0,0", generateChunk(0, 0, 199307), []);
  for (let i = 0; i < 30; i++) motor.move(0, 0, 1 / 60, position);
  assert.ok(position.y > 1.6 && position.y < 1.8);
  motor.clearSections();
  motor.teleport({ x: 12, z: 21.6 });
  motor.addSection("0,0", generateChunk(0, 0, 199307, 1), []);
  for (let i = 0; i < 30; i++) motor.move(0, -0.03, 1 / 60, position);
  assert.ok(position.z < 21 && position.y > 1.6);
  motor.dispose();
});

import assert from "node:assert/strict";
import test from "node:test";
import { gaitUrgency, solveEntityLeg, stepLength } from "../src/lib/game/entity-gait";

test("swing feet leave and meet the floor with zero vertical and toe-pitch velocity", () => {
  const epsilon = 1e-5;
  for (const speed of [0.38, 1.2, 2.85, 4.65]) {
    for (const motion of [0.1, 0.5, 1]) {
      const solve = (gait: number) => solveEntityLeg(gait, speed, motion, 1.15);
      const toe = (gait: number) => {
        const { hip, knee, ankle } = solve(gait);
        return hip + knee + ankle;
      };
      for (const boundary of [Math.PI / 2, Math.PI * 1.5]) {
        const left = solve(boundary - epsilon), right = solve(boundary + epsilon);
        assert.ok(Math.abs((right.footY - left.footY) / (2 * epsilon)) < 1e-4);
        assert.ok(Math.abs((toe(boundary + epsilon) - toe(boundary - epsilon)) / (2 * epsilon)) < 1e-4);
        assert.ok(Math.abs(solve(boundary).footY - 0.05) < 1e-10);
      }
      const apex = solve(Math.PI);
      assert.ok(Math.abs(apex.footY - (0.05 + (0.15 + gaitUrgency(speed) * 0.18) * motion)) < 1e-10, "peak clearance is unchanged");
      const first = solve(-Math.PI / 2), last = solve(Math.PI / 2);
      assert.ok(Math.abs(first.footZ - last.footZ - stepLength(speed) * motion) < 1e-10, "stride length is unchanged");
      for (let i = 0; i <= 240; i++) {
        const pose = solve(i * Math.PI / 120);
        assert.ok(pose.footY >= 0.05);
        assert.ok([pose.hip, pose.knee, pose.ankle].every(Number.isFinite));
      }
    }
  }
});

import assert from "node:assert/strict";
import test from "node:test";
import { nextTape, parseTape, tapeUrl } from "../src/lib/game/tape";

test("old tape URLs remain v1 while new recordings default to v2", () => {
  const parse = (query: string) => parseTape(new URLSearchParams(query), () => 456789);
  assert.deepEqual(parse("tape=199307"), { seed: 199307, generation: 1 });
  assert.deepEqual(parse("tape=0"), { seed: 0, generation: 1 });
  assert.deepEqual(parse(""), { seed: 456789, generation: 2 });
  for (const invalid of ["", "abc", "-1", "1000000000", "1.5"])
    assert.deepEqual(parse(`tape=${invalid}`), { seed: 456789, generation: 2 });
  assert.deepEqual(parse("tape=199307&generation=2"), { seed: 199307, generation: 2 });
  assert.deepEqual(parse("generation=1"), { seed: 456789, generation: 1 });
  for (const unsupported of ["", "3", "02", "latest", "-1"])
    assert.equal(parse(`tape=199307&generation=${unsupported}`).generation, 1);
  assert.equal(parse("generation=999").generation, 1);
  parseTape(new URLSearchParams("tape=123"), () => { throw Error("valid tape must not consume random seed"); });
});

test("copied and compatible-camera URLs preserve seed, version and other parameters", () => {
  for (const generation of [1, 2] as const)
    for (const seed of [0, 199307]) {
      const tape = { seed, generation };
      const url = tapeUrl("https://vackrooms.vercel.app/?visit=poolroom&renderer=webgpu#recording", tape);
      assert.equal(url.searchParams.get("visit"), "poolroom");
      assert.equal(url.hash, "#recording");
      assert.deepEqual(parseTape(url.searchParams, () => 999), tape);
      url.searchParams.set("renderer", "webgl");
      assert.deepEqual(parseTape(url.searchParams, () => 999), tape);
    }
});

test("next-life tape links preserve generation through repeated death and reload", () => {
  for (const generation of [1, 2] as const) {
    let tape = { seed: 199307, generation };
    for (let life = 0; life < 5; life++) {
      const next = nextTape(tape);
      assert.notEqual(next.seed, tape.seed);
      assert.equal(next.generation, generation);
      assert.deepEqual(nextTape(tape), next);
      tape = parseTape(tapeUrl("https://vackrooms.vercel.app/", next).searchParams, () => 999);
      assert.deepEqual(tape, next);
    }
  }
});

import assert from "node:assert/strict";
import test from "node:test";
import { Vector3 } from "three";
import { CELL, SPAN, generateChunk } from "../src/lib/game/maze";
import { houseLots } from "../src/lib/game/neighborhood";
import { CharacterMotor } from "../src/lib/game/physics";
import { buildSection } from "../src/lib/game/world";
import { headlessMaterials } from "./helpers/materials";

test("neighborhood double jumps hit pitched roofs and can return to the street", async () => {
  // The nearest street on ?tape=199307&visit=neighborhood includes narrow
  // gables and wide houses with both ridge orientations, on both sides.
  const data = generateChunk(-3, -3, 199307);
  assert.equal(data.landmark.kind, "neighborhood");
  const mats = headlessMaterials(), section = buildSection(data, mats, 0);
  const room = data.landmark;
  const orientations = new Set<string>();
  try {
    for (const lot of houseLots(data)) {
      orientations.add(lot.rows === 1 || (lot.style >>> 3) % 2 === 0 ? "gable" : "parallel");
      const inward = -lot.side;
      const edge = (lot.side < 0 ? room.x : room.x + room.width) * CELL + data.x * SPAN;
      const center = (room.z + lot.row + lot.rows / 2) * CELL + data.z * SPAN;
      const flip = (lot.style >>> 4) % 2 ? 1 : -1;
      const doorAt = flip * (lot.rows === 2 ? -1.1 : -0.75);
      const motor = await CharacterMotor.create({ x: edge + inward * 4.1, z: center + doorAt });
      const position = new Vector3();
      try {
        motor.addSection("street", data, section.colliders, section.shapedColliders);
        for (let i = 0; i < 40; i++) motor.move(-inward * 0.01, 0, 1 / 60, position);
        for (let i = 0; i < 180; i++) {
          if (i === 0 || i === 18) motor.jump();
          motor.move(i < 70 ? -inward * 0.025 : 0, 0, 1 / 60, position);
        }
        assert.ok(motor.grounded, "a roof collision must not leave the player suspended");
        assert.ok(position.y < 2, `lot ${lot.side}/${lot.row} lands on its porch, not inside the roof`);
        assert.ok((position.x - edge) * inward > 3.5, "player stays outside the sealed house");
        for (let i = 0; i < 180; i++) motor.move(inward * 0.045, 0, 1 / 60, position);
        assert.ok((position.x - edge) * inward > 10, "the porch still exits onto the street");
        assert.ok(motor.grounded && Math.abs(position.y - 1.66) < 0.03);
      } finally {
        motor.dispose();
      }
    }
    assert.equal(orientations.size, 2);
  } finally {
    section.dispose();
    mats.dispose();
  }
});

import assert from "node:assert/strict";
import test from "node:test";
import { roomImpulse } from "../src/lib/game/room-impulse";
import { ROOM_SOUNDS, type RoomSound } from "../src/lib/game/acoustics";

test("room responses are seeded, stereo, finite, and have no direct impulse", () => {
  for (const room of Object.keys(ROOM_SOUNDS) as RoomSound[]) {
    const channels = roomImpulse(room, 24000, 42);
    assert.deepEqual(channels, roomImpulse(room, 24000, 42));
    assert.notDeepEqual(channels[0], channels[1]);
    assert.notDeepEqual(channels, roomImpulse(room, 24000, 43));
    for (const channel of channels) {
      assert.equal(channel.length, Math.ceil(24000 * ROOM_SOUNDS[room].decay));
      assert.ok(channel.every(Number.isFinite));
      assert.ok(channel.slice(0, 240).every((sample) => sample === 0));
      const energy = (from: number, to: number) => channel.slice(from, to).reduce((sum, v) => sum + v * v, 0);
      assert.ok(energy(240, 2400) > energy(channel.length - 2400, channel.length));
    }
  }
});

test("pool and hall reflections arrive later than the small carpeted office", () => {
  const onset = (room: RoomSound) => roomImpulse(room, 48000, 42)[0].findIndex((sample) => sample !== 0) / 48000;
  assert.ok(onset("hall") > onset("office"));
  assert.ok(onset("pool") > onset("office"));
});

test("late reflections lose high-frequency energy as the room absorbs sound", () => {
  const sampleRate = 24000;
  for (const room of ["hall", "pool", "corridor"] as const) {
    const samples = roomImpulse(room, sampleRate, 42)[0];
    const brightness = (from: number, to: number) => {
      let difference = 0, energy = 0;
      for (let i = Math.floor(from * sampleRate); i < Math.floor(to * sampleRate); i++) {
        energy += samples[i] ** 2;
        difference += (samples[i] - samples[i - 1]) ** 2;
      }
      return difference / energy;
    };
    assert.ok(brightness(0.04, 0.12) > brightness(0.35, 0.55));
  }
});

import assert from "node:assert/strict";
import test from "node:test";
import { PropSoundGate, propSoundSamples } from "../src/lib/game/prop-sounds";

test("prop foley ignores spawn settling, resting jitter, and airborne movement", () => {
  const gate = new PropSoundGate();
  assert.equal(gate.sample(0.1, 1, 1, true), null);
  for (let i = 0; i < 120; i++) assert.equal(gate.sample(1 / 60, 0.05, 0.1, true), null);
  for (let i = 0; i < 120; i++) assert.equal(gate.sample(1 / 60, 2, 0, false), null);
  assert.equal(gate.sample(1 / 60, 0, 1.5, true)?.kind, "impact", "landing contact sounds even without sliding");
});

test("scraping and repeated impact contacts have bounded cadence and strength", () => {
  const gate = new PropSoundGate(); gate.sample(0.5, 0, 0, false);
  let scrapes = 0, impacts = 0;
  for (let i = 0; i < 120; i++) {
    const event = gate.sample(1 / 120, 2, 0, true);
    if (event) { scrapes++; assert.ok(event.strength <= 1); }
  }
  assert.ok(scrapes >= 4 && scrapes <= 6);
  for (let i = 0; i < 120; i++) {
    const event = gate.sample(1 / 120, 0, 20, true);
    if (event) { impacts++; assert.equal(event.kind, "impact"); assert.equal(event.strength, 1); }
  }
  assert.ok(impacts >= 4 && impacts <= 5);
});

test("all material foley is short, finite, repeatable, and fades to silence", () => {
  for (const kind of ["scrape", "impact"] as const)
    for (const material of ["wood", "metal", "plastic", "cardboard"] as const)
      for (const sampleRate of [44100, 48000]) {
        const samples = propSoundSamples(kind, material, sampleRate);
        assert.deepEqual(samples, propSoundSamples(kind, material, sampleRate));
        assert.ok(samples.length <= sampleRate * 0.25);
        assert.ok(samples.every(x => Number.isFinite(x) && Math.abs(x) < 0.9));
        assert.ok(Math.abs(samples[0]) < 0.000001 && Math.abs(samples.at(-1)!) < 0.000001);
        const rms = Math.sqrt(samples.reduce((sum, x) => sum + x * x, 0) / samples.length);
        assert.ok(rms > 0.01 && rms < 0.2);
      }
});

import assert from "node:assert/strict";
import test from "node:test";
import { Material, Mesh } from "three";
import { generateChunk } from "../src/lib/game/maze";
import { buildSection } from "../src/lib/game/world";
import { headlessMaterials } from "./helpers/materials";

test("retiring a section releases object bindings and geometry without disposing shared materials or neighbors", () => {
  const mats = headlessMaterials();
  const shared = new Set(Object.values(mats).flat().filter((value) => value instanceof Material));
  let sharedDisposals = 0;
  for (const material of shared) material.addEventListener("dispose", () => sharedDisposals++);
  const sections = [0, 1].map((x) => buildSection(generateChunk(x, 0, 199307), mats, 0));
  const records = sections.map((section) => {
    const meshes: { object: number; geometry: number }[] = [];
    section.group.traverse((object) => {
      if (!(object instanceof Mesh)) return;
      const record = { object: 0, geometry: 0 };
      object.addEventListener("dispose", () => record.object++);
      object.geometry.addEventListener("dispose", () => record.geometry++);
      meshes.push(record);
    });
    assert.ok(meshes.length > 10, "exercise actual generated architecture and furniture batches");
    return meshes;
  });
  try {
    sections[0].dispose();
    assert.ok(records[0].every((record) => record.object === 1 && record.geometry === 1));
    assert.ok(records[1].every((record) => record.object === 0 && record.geometry === 0), "resident neighbor retains its resources");
    assert.equal(sharedDisposals, 0, "shared materials stay alive across streaming");
    sections[1].dispose();
    assert.ok(records[1].every((record) => record.object === 1 && record.geometry === 1));
    assert.equal(sharedDisposals, 0);
  } finally {
    // An assertion failure must still release any section not retired above.
    sections.forEach((section, i) => {
      if (records[i].every((record) => record.geometry === 0)) section.dispose();
    });
    mats.dispose();
  }
});
